   247→            'SELECT role FROM users WHERE username=? AND password=?',
   248→            (username, password)
   249→        )
   250→
   251→        if result:
   252→            self.user_role = result[0]
   253→            self.username = username
   254→            self.accept()
   255→        else:
   256→            self.show_message('错误', '用户名或密码错误！', QMessageBox.Critical)
