import sqlite3
from datetime import datetime
from PyQt5.QtWidgets import (
    QApplication, QMainWindow, QWidget, QVBoxLayout, QHBoxLayout,
    QLabel, QLineEdit, QPushButton, QTableWidget, QTableWidgetItem,
    QMessageBox, QDialog, QTabWidget, QComboBox, QDateEdit, QHeaderView,
    QTextEdit, QGridLayout, QGroupBox, QSplitter, QFileDialog, QFrame
)
from PyQt5.QtCore import Qt, QDate
from PyQt5.QtGui import QFont, QColor


def show_styled_message(parent, title, text, icon=QMessageBox.Information):
    """显示统一样式的消息框"""
    msg = QMessageBox(parent)
    msg.setWindowTitle(title)
    msg.setText(text)
    msg.setIcon(icon)
    msg.setStyleSheet("""
        QMessageBox {
            background-color: white;
        }
        QLabel {
            color: #212121;
            font-size: 16px;
            min-width: 240px;
            padding: 10px;
        }
        QPushButton {
            background-color: #2196F3;
            color: white;
            border: none;
            padding: 8px 24px;
            border-radius: 4px;
            font-size: 16px;
            font-weight: bold;
            min-width: 70px;
        }
        QPushButton:hover {
            background-color: #1976D2;
        }
    """)
    return msg.exec_()



class WageCalculationTab(QWidget):
    """工资核算标签页"""

    def __init__(self, db_manager, user_role, username):
        super().__init__()
        self.db_manager = db_manager
        self.user_role = user_role
        self.username = username
        self.init_ui()

    def init_ui(self):
        layout = QVBoxLayout()
        layout.setContentsMargins(15, 15, 15, 15)
        layout.setSpacing(12)

        # ===== 操作按钮区域 =====
        button_card = QFrame()
        button_card.setStyleSheet("""
            QFrame {
                background-color: white;
                border: 1px solid #E0E0E0;
                border-radius: 4px;
            }
        """)

        btn_layout = QHBoxLayout()
        btn_layout.setContentsMargins(15, 12, 15, 12)
        btn_layout.setSpacing(10)

        refresh_btn = QPushButton('刷新')
        refresh_btn.clicked.connect(self.load_data)
        refresh_btn.setCursor(Qt.PointingHandCursor)
        refresh_btn.setFont(QFont('Microsoft YaHei', 13))
        refresh_btn.setFixedHeight(46)
        refresh_btn.setStyleSheet("""
            QPushButton {
                background-color: #2196F3;
                color: white;
                border: none;
                border-radius: 4px;
                padding: 0 24px;
            }
            QPushButton:hover {
                background-color: #1976D2;
            }
        """)
        btn_layout.addWidget(refresh_btn)

        if self.user_role == 'finance':
            add_btn = QPushButton('添加记录')
            add_btn.clicked.connect(self.add_record)
            add_btn.setCursor(Qt.PointingHandCursor)
            add_btn.setFont(QFont('Microsoft YaHei', 13))
            add_btn.setFixedHeight(46)
            add_btn.setStyleSheet("""
                QPushButton {
                    background-color: #4CAF50;
                    color: white;
                    border: none;
                    border-radius: 4px;
                    padding: 0 24px;
                }
                QPushButton:hover {
                    background-color: #45A049;
                }
            """)
            btn_layout.addWidget(add_btn)

        btn_layout.addStretch()
        button_card.setLayout(btn_layout)
        layout.addWidget(button_card)

        # ===== 表格区域 =====
        table_card = QFrame()
        table_card.setStyleSheet("""
            QFrame {
                background-color: white;
                border: 1px solid #E0E0E0;
                border-radius: 4px;
            }
        """)

        table_layout = QVBoxLayout()
        table_layout.setContentsMargins(15, 15, 15, 15)

        self.table = QTableWidget()
        self.table.setColumnCount(8)
        self.table.setHorizontalHeaderLabels([
            'ID', '加工车间', '织片数量', '织片工资',
            '套口货物', '套口工资', '手缝货物', '创建人'
        ])

        # 表格样式美化
        self.table.setStyleSheet("""
            QTableWidget {
                background-color: white;
                border: none;
                gridline-color: #E0E0E0;
                font-size: 16px;
            }
            QTableWidget::item {
                padding: 10px 8px;
                border-bottom: 1px solid #F5F5F5;
            }
            QTableWidget::item:selected {
                background-color: #E3F2FD;
                color: #212121;
            }
            QTableWidget::item:hover {
                background-color: #F5F5F5;
            }
            QHeaderView::section {
                background-color: #FAFAFA;
                color: #424242;
                padding: 12px 8px;
                border: none;
                border-bottom: 2px solid #E0E0E0;
                font-weight: bold;
                font-size: 16px;
            }
        """)

        self.table.horizontalHeader().setSectionResizeMode(QHeaderView.Stretch)
        self.table.setSelectionBehavior(QTableWidget.SelectRows)
        self.table.setAlternatingRowColors(True)

        table_layout.addWidget(self.table)
        table_card.setLayout(table_layout)
        layout.addWidget(table_card)

        self.setLayout(layout)
        self.load_data()

    def load_data(self):
        """加载数据"""
        query = '''
            SELECT id, workshop_name, knitting_qty, knitting_wage,
                   overlock_goods_type, overlock_wage,
                   hand_sewing_goods_type, created_by
            FROM wage_calculation
            ORDER BY id DESC
        '''
        results = self.db_manager.fetch_all(query)

        self.table.setRowCount(len(results))
        for row, data in enumerate(results):
            for col, value in enumerate(data):
                # 格式化显示
                if col in [4, 6]:  # 货物种类列
                    display_value = value if value else '-'
                else:
                    display_value = str(value) if value else ''

                item = QTableWidgetItem(display_value)
                item.setFlags(item.flags() & ~Qt.ItemIsEditable)
                self.table.setItem(row, col, item)

    def add_record(self):
        """添加记录"""
        dialog = WageCalculationDialog(self.db_manager, self.username)
        if dialog.exec_() == QDialog.Accepted:
            self.load_data()


