   376→            SELECT id, goods_type, customer_name,
   377→                customer_send_qty, factory_receive_qty, diff_receive,
   378→                factory_send_qty, customer_receive_qty, diff_factory_customer,
   379→                COALESCE(modified_date, created_date), 
   380→                COALESCE(modified_by, created_by, '-')
   381→            FROM goods_processing_v2
   382→        '''
   383→        
   384→        params = []
   385→        current_type = self.type_filter.currentText()
   386→        if current_type != '全部':
   387→            base_query += ' WHERE goods_type = ?'
   388→            params.append(current_type)
   389→        
   390→        base_query += ' ORDER BY id DESC'
   391→        
   392→        results = self.db_manager.fetch_all(base_query, params if params else None)
   393→        self._populate_table(results)
