   398→        if not keyword:
   399→            self.load_data()
   400→            return
   401→        
   402→        base_query = '''
   403→            SELECT id, goods_type, customer_name,
   404→                customer_send_qty, factory_receive_qty, diff_receive,
   405→                factory_send_qty, customer_receive_qty, diff_factory_customer,
   406→                COALESCE(modified_date, created_date), 
   407→                COALESCE(modified_by, created_by, '-')
   408→            FROM goods_processing_v2
   409→            WHERE (customer_name LIKE ?)
   410→        '''
   411→        
   412→        params = [f'%{keyword}%', f'%{keyword}%']
   413→        current_type = self.type_filter.currentText()
   414→        if current_type != '全部':
   415→            base_query += ' AND goods_type = ?'
   416→            params.append(current_type)
   417→        
   418→        base_query += ' ORDER BY id DESC'
   419→        results = self.db_manager.fetch_all(base_query, params)
   420→        self._populate_table(results)
