   422→    def _populate_table(self, results):
   423→        """统一表格填充逻辑（含差异高亮）"""
   424→        self.table.setRowCount(len(results))
   425→        
   426→        # 用于统计的变量
   427→        total_customer_send = 0
   428→        total_factory_receive = 0
   429→        total_factory_send = 0
   430→        total_customer_receive = 0
   431→        
   432→        for row, data in enumerate(results):
   433→            # 累加统计数据（跳过可能的None值）
   434→            if len(data) > 8:  # 确保有足够的数据列
   435→                try:
   436→                    total_customer_send += int(data[4] or 0)
   437→                    total_factory_receive += int(data[5] or 0)
   438→                    total_factory_send += int(data[7] or 0)
   439→                    total_customer_receive += int(data[8] or 0)
   440→                except (ValueError, TypeError, IndexError):
   441→                    pass
   442→            
   443→            for col, value in enumerate(data):
