            color: white;
            border: none;
            padding: 8px 24px;
            border-radius: 4px;
            font-size: 16px;
            font-weight: bold;
            min-width: 70px;
        }
        QPushButton:hover {
            background-color: #1976D2;
        }
    """)
    return msg.exec_()


class GoodsProcessingTab(QWidget):
